import random

suits = ['♠', '♥', '♦', '♣']
ranks = [ '2', '3', '4', '5', '6', '7', '8', '9', '10', 'A', 'J', 'Q', 'K']
cards = []

face_cards = ['J', 'Q', 'K']

for suit in suits:
    for rank in ranks:
        cards.append([suit, rank])

random.shuffle(cards) 

player_cards = random.choices(cards, k=2)
dealer_cards = random.choices(cards, k=2)

formatted_cards = [f"{suit}{rank}" for suit, rank in player_cards] # ! Crucial: we used the list comprehension technique to unpack the list of lists the right way

